            "if (isChatRunTerminalStatus(status))",
            "rememberRunApprovalDetails(run)",
            "setStatus(nextApprovalStatusText(run))",
            "createDelegatedRunSummary(runId, createDelegatedRunSummaryOptions())",
            "chatRunCompletionProcessingState(",
