            "<h1>能力中心</h1>",
            "管理记忆、提醒、文件、语音和 Agent 协作。",
            "const LEGACY_TOOL_CATEGORIES = new Set(['外部服务', '第三方扩展']);",
            ").filter(isUserFacingTool);",
            "return !LEGACY_TOOL_CATEGORIES.has(item.category);",
            "label: '语音播报'",
            "label: '文件与工作区'",
            "id: 'artifact'",
            "label: '产物输出'",
            "label: 'Long-term Memory'",
