            "id: 'future_task'",
            "label: 'FutureTask 排程'",
            "future_task.schedule/list/cancel",
            "aliases: ['future-task', 'cronjob', 'cron', 'future_task.schedule', 'future_task.list', 'future_task.cancel']",
            "label: 'Agent / Workflow 委派'",
